function canAcknowledgeCommit(logAppended, logFsynced) {
  return Boolean(logAppended && logFsynced);
}

function shouldFlushBatch(pendingCount, maxBatchSize) {
  return pendingCount >= maxBatchSize;
}

function isEntryValid(payload, storedChecksum, computeChecksum) {
  return computeChecksum(payload) === storedChecksum;
}

function replayUntilCorrupt(entries) {
  const state = {};
  for (const { key, value, valid } of entries) {
    if (!valid) break;
    state[key] = value;
  }
  return state;
}

